<body class="gh-shell"><?php require dirname(__DIR__).'/partials/header.php'; ?><main id="main-content" tabindex="-1" class="gh-bids-layout"><p class="gh-bids-eyebrow">CLIENT WORKSPACE</p><h1>Bids for <?= $escape($job['title']) ?></h1><p>Review Freelancer proposals. Awarding, escrow and payments are not available in this module.</p><a href="?route=/client/jobs/show&amp;id=<?= (int)$job['id'] ?>">Back to your job</a>
